test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 37 }), 370);
});

test('lineTotal works with qty of 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
});

test('invoiceTotals sums line totals for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 5, unitPrice: 8500, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { qty: 2, unitPrice: 8500, vatRate: 0 },
      { qty: 8, unitPrice: 9500, vatRate: 0 },
      { qty: 3, unitPrice: 980, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 8 * 9500 + 3 * 980);
  assert.equal(totals.subtotal, 17000 + 76000 + 2940);
  assert.equal(totals.subtotal, 95940);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 95940);
});

test('invoiceTotals returns new object on each call', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
  };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals with empty lines', () => {
  const invoice = {
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('addLine adds a new line to the end', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].qty, 5);
  assert.equal(result.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already on invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].unitPrice, 8500);
});

test('addLine rejects invalid qty', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -1 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

